function budgetCostFor(hours){return Number(hours||0)*averageCurrentCostRate()}
function addDays(date,days){const value=new Date(`${date}T00:00:00Z`);value.setUTCDate(value.getUTCDate()+days);return value.toISOString().slice(0,10)}
function approvedTimeFor(engagementId){return timesheets.filter(entry=>entry.engagementId===engagementId&&entry.status==="Approved")}
function wipFor(engagement){const financial=financialFor(engagement.id),time=approvedTimeFor(engagement.id),hours=time.reduce((sum,entry)=>sum+Number(entry.hoursSpent),0),actualCost=time.reduce((sum,entry)=>sum+Number(entry.costAtApproval||latestApplicableRate(entry.staffId,entry.dateLogged)?.standardCostRate||0)*Number(entry.hoursSpent),0),totalBilled=invoicesFor(engagement.id).reduce((sum,invoice)=>sum+Number(invoice.amountBilled),0),agreedFee=Number(financial?.agreedFee||0),budgetedHours=Number(financial?.budgetedHours||0),unbilledWip=Math.max(0,agreedFee-totalBilled),costToFee=agreedFee?actualCost/agreedFee*100:0;return{financial,hours,actualCost,totalBilled,agreedFee,budgetedHours,unbilledWip,costToFee,budgetVariance:hours-budgetedHours}}
function writeAlert(alertCode,relatedRecordId,recipientPosition,detail){const today=operationDate(),exists=systemAlerts.some(alert=>alert.alertCode===alertCode&&alert.relatedRecordId===relatedRecordId&&alert.recipientPosition===recipientPosition&&alert.createdAt.slice(0,10)===today);if(exists)return false;systemAlerts.push({id:crypto.randomUUID(),alertCode,relatedRecordId,recipientPosition,detail,status:"Pending",createdAt:new Date().toISOString()});return true}
function showOperationsNotice(message,error=false){const notice=document.getElementById("operationsNotice");notice.textContent=message;notice.classList.add("show");notice.style.background=error?"#fbe8e8":"";notice.style.borderColor=error?"#d8aaaa":"";notice.style.color=error?"#8b2828":"";clearTimeout(showOperationsNotice.timer);showOperationsNotice.timer=setTimeout(()=>notice.classList.remove("show"),8000)}
function showVaultNotice(message,error=false){const notice=document.getElementById("vaultNotice");notice.textContent=message;notice.classList.add("show");notice.style.background=error?"#fbe8e8":"";notice.style.borderColor=error?"#d8aaaa":"";notice.style.color=error?"#8b2828":"";clearTimeout(showVaultNotice.timer);showVaultNotice.timer=setTimeout(()=>notice.classList.remove("show"),8000)}
function renderStaffRates(){const target=document.getElementById("staffRatesTable");target.innerHTML=staffRates.length?staffRates.slice().sort((a,b)=>b.effectiveDate.localeCompare(a.effectiveDate)).map(rate=>`<tr><td>${escapeHtml(rate.staffId)}</td><td>${escapeHtml(rate.position||"Not set")}</td><td>${formatKes(rate.standardCostRate)}</td><td>${formatKes(rate.billableRate)}</td><td>${escapeHtml(rate.effectiveDate)}</td><td>${escapeHtml(rate.endDate||"Current")}</td></tr>`).join(""):'<tr><td colspan="6" class="hint">No staff rate history recorded.</td></tr>'}
function renderApprovalQueue(){const target=document.getElementById("approvalQueue"),queue=timesheets.filter(entry=>["Submitted","Approved","Rejected"].includes(entry.status)).slice().reverse();target.innerHTML=queue.length?queue.map(entry=>{const engagement=engagementById(entry.engagementId);return `<tr><td>${escapeHtml(entry.staffId)}<br><span class="hint">${escapeHtml(engagement?.companyName||"Archived engagement")}</span></td><td>${entry.hoursSpent}</td><td>${escapeHtml(entry.description)}</td><td>${escapeHtml(entry.status)}${entry.approvedBy?`<br><span class="hint">By ${escapeHtml(entry.approvedBy)}</span>`:""}</td><td>${entry.status==="Submitted"?`<button data-timesheet-action="approve" data-id="${entry.id}">Approve</button> <button data-timesheet-action="reject" data-id="${entry.id}">Reject</button>`:entry.status==="Approved"?`<button data-timesheet-action="reverse" data-id="${entry.id}">Create reversal</button>`:"—"}</td></tr>`}).join(""):'<tr><td colspan="5" class="hint">No submitted timesheets awaiting review.</td></tr>'}
function renderWipTable(){const target=document.getElementById("wipTable"),active=activeEngagements();target.innerHTML=active.length?active.map(engagement=>{const wip=wipFor(engagement),risk=wip.agreedFee&&wip.costToFee>70,loss=wip.agreedFee&&wip.actualCost>wip.agreedFee;return `<tr><td>${escapeHtml(engagementLabel(engagement))}</td><td>${wip.financial?formatKes(wip.agreedFee):"Baseline not set"}</td><td>${wip.hours.toFixed(2)}</td><td>${formatKes(wip.actualCost)}</td><td>${formatKes(wip.totalBilled)}</td><td>${formatKes(wip.unbilledWip)}</td><td class="${loss?"status-risk":risk?"status-watch":"status-ok"}">${wip.agreedFee?`${wip.costToFee.toFixed(1)}%`:"—"}</td><td class="${wip.budgetVariance>0?"status-risk":""}">${wip.financial?`${wip.budgetVariance.toFixed(2)} hrs`:"—"}</td><td>${loss?`<button data-wip-action="loss" data-id="${engagement.id}">Loss decision</button>`:`<button data-wip-action="invoice" data-id="${engagement.id}">Prepare invoice</button>`}</td></tr>`}).join(""):'<tr><td colspan="9" class="hint">Activate an engagement in the lifecycle module to begin WIP tracking.</td></tr>'}
function renderOperations(){refreshOperationalSelects();renderStaffRates();renderApprovalQueue();renderWipTable();renderDashboard()}
function recordTimesheetEntries(form){const data=new FormData(form),engagement=engagementById(data.get("timesheetEngagement")),staffId=data.get("timesheetStaffId").trim(),weekStart=data.get("timesheetWeekStart"),hours=["hoursMon","hoursTue","hoursWed","hoursThu","hoursFri","hoursSat","hoursSun"].map(name=>Number(data.get(name)||0)),total=hours.reduce((sum,value)=>sum+value,0);if(!engagement||!data.get("timesheetTask")||!staffId||!weekStart||!total){showOperationsNotice("Select an active engagement and task, enter a staff ID, week, description and at least one hour.",true);return}hours.forEach((hoursSpent,index)=>{if(!hoursSpent)return;timesheets.push({id:crypto.randomUUID(),staffId,position:data.get("timesheetPosition"),engagementId:engagement.id,taskId:data.get("timesheetTask"),dateLogged:addDays(weekStart,index),hoursSpent,description:data.get("timesheetDescription").trim(),status:data.get("timesheetStatus"),approvedBy:null,approvedAt:null,locked:false,entryType:"Standard",createdAt:new Date().toISOString()})});saveOperations();form.reset();document.getElementById("timesheetStatus").value="Draft";renderOperations();showOperationsNotice(`${total.toFixed(2)} hours saved as ${data.get("timesheetStatus")}. Submitted entries will be locked after Manager approval.`)}
function initialiseOperations(){
  document.getElementById("staffRateForm").addEventListener("submit",event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),staffId=data.get("rateStaffId").trim(),effectiveDate=data.get("rateEffectiveDate"),endDate=data.get("rateEndDate");if(endDate&&endDate<effectiveDate){showOperationsNotice("A rate end date cannot be earlier than its effective date.",true);return}staffRates.push({id:crypto.randomUUID(),staffId,position:data.get("ratePosition"),standardCostRate:Number(data.get("standardCostRate")),billableRate:Number(data.get("billableRate")),effectiveDate,endDate});saveOperations();form.reset();renderOperations();showOperationsNotice("Staff rate history saved. Approved time will use the rate applicable on its work date.")});
  document.getElementById("timesheetEngagement").addEventListener("change",renderTimesheetTaskOptions);document.getElementById("timesheetForm").addEventListener("submit",event=>{event.preventDefault();if(!event.currentTarget.reportValidity())return;recordTimesheetEntries(event.currentTarget)});
  document.getElementById("financialEngagement").addEventListener("change",()=>{const financial=financialFor(document.getElementById("financialEngagement").value);document.getElementById("agreedFee").value=financial?.agreedFee||"";document.getElementById("budgetedHours").value=financial?.budgetedHours||"";document.getElementById("budgetedCost").value=financial?.budgetedCost||"";document.getElementById("billingStatus").value=financial?.billingStatus||"Unbilled"});
  document.getElementById("budgetedHours").addEventListener("input",event=>document.getElementById("budgetedCost").value=budgetCostFor(event.target.value)||"");document.getElementById("financialsForm").addEventListener("submit",event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),engagementId=data.get("financialEngagement"),cost=budgetCostFor(data.get("budgetedHours"));if(!averageCurrentCostRate()){showOperationsNotice("Create an effective staff cost rate before calculating the engagement budgeted cost.",true);return}const record={id:financialFor(engagementId)?.id||crypto.randomUUID(),engagementId,agreedFee:Number(data.get("agreedFee")),budgetedHours:Number(data.get("budgetedHours")),budgetedCost:cost,billingStatus:data.get("billingStatus"),updatedAt:new Date().toISOString()};const index=engagementFinancials.findIndex(item=>item.engagementId===engagementId);if(index>=0)engagementFinancials[index]=record;else engagementFinancials.push(record);saveOperations();document.getElementById("budgetedCost").value=cost;renderOperations();showOperationsNotice("Engagement financial baseline saved separately from the Engagement Letter record.")});
  document.getElementById("invoiceForm").addEventListener("submit",event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),engagementId=data.get("invoiceEngagement"),number=data.get("invoiceNumber").trim();if(invoices.some(invoice=>invoice.invoiceNumber===number)){showOperationsNotice("Invoice number already exists.",true);return}invoices.push({id:crypto.randomUUID(),engagementId,invoiceNumber:number,amountBilled:Number(data.get("invoiceAmount")),vatAmount:Number(data.get("invoiceVat")||0),dateIssued:data.get("invoiceDateIssued"),datePaid:data.get("invoiceDatePaid")||null,createdAt:new Date().toISOString()});const financial=financialFor(engagementId);if(financial){const billed=invoicesFor(engagementId).reduce((sum,invoice)=>sum+Number(invoice.amountBilled),0);financial.billingStatus=billed>=financial.agreedFee?invoicesFor(engagementId).every(invoice=>invoice.datePaid)?"Paid":"Fully Billed":"Partially Billed"}saveOperations();form.reset();renderOperations();showOperationsNotice("Invoice recorded against the engagement.")});
  document.getElementById("approvalQueue").addEventListener("click",event=>{const button=event.target.closest("button[data-timesheet-action]");if(!button)return;const entry=timesheets.find(item=>item.id===button.dataset.id);if(!entry)return;if(button.dataset.timesheetAction==="approve"){const managerId=prompt("Enter the approving Manager staff ID.");if(!managerId)return;const rate=latestApplicableRate(entry.staffId,entry.dateLogged);if(!rate){showOperationsNotice("Approval is blocked because there is no effective staff cost rate for this timesheet date.",true);return}entry.status="Approved";entry.approvedBy=managerId;entry.approvedAt=new Date().toISOString();entry.costAtApproval=rate.standardCostRate;entry.locked=true;showOperationsNotice("Timesheet approved and locked. Any correction must use a reversal entry.")}if(button.dataset.timesheetAction==="reject"){const reason=prompt("Enter the rejection reason.");if(!reason)return;entry.status="Rejected";entry.rejectionReason=reason;showOperationsNotice("Timesheet rejected and returned for correction.")}if(button.dataset.timesheetAction==="reverse"){timesheets.push({id:crypto.randomUUID(),staffId:entry.staffId,position:entry.position,engagementId:entry.engagementId,taskId:entry.taskId,dateLogged:operationDate(),hoursSpent:-Number(entry.hoursSpent),description:`Reversal of locked entry ${entry.id}: ${entry.description}`,status:"Submitted",approvedBy:null,approvedAt:null,locked:false,entryType:"Reversal",createdAt:new Date().toISOString()});showOperationsNotice("A separate negative reversal entry has been created for Manager approval.")}saveOperations();renderOperations()});
  document.getElementById("wipTable").addEventListener("click",event=>{const button=event.target.closest("button[data-wip-action]");if(!button)return;const engagement=engagementById(button.dataset.id),financial=financialFor(button.dataset.id),wip=wipFor(engagement);if(button.dataset.wipAction==="loss"){const decision=prompt("Record the Partner decision: write off overrun or issue supplementary invoice.");if(!decision)return;financial.lossDecision=decision;financial.lossDecisionAt=new Date().toISOString();saveOperations();renderOperations();showOperationsNotice("Loss decision recorded against the engagement financials.")}else{document.getElementById("invoiceEngagement").value=engagement.id;document.getElementById("invoiceAmount").value=Math.max(0,wip.agreedFee-wip.totalBilled);showOperationsNotice("Invoice form prepared with the remaining agreed fee. Confirm the amount before recording.")}});
  document.getElementById("runOperationsControls").addEventListener("click",()=>{runFirmPulseControls();saveOperations();renderOperations();showOperationsNotice("WIP, billing and loss controls have been scanned.")});renderOperations()
}
function documentCategory(id){return vaultCategories.find(category=>category.id===id)}
function logDocumentAction(documentRecord,actionType,actorId){documentLogs.push({id:crypto.randomUUID(),documentId:documentRecord.id,documentName:documentRecord.fileName,actionType,actorId,actionTimestamp:new Date().toISOString()})}
function renderVault(){const categories=document.getElementById("vaultCategories"),categorySelect=document.getElementById("documentCategory");categories.innerHTML=vaultCategories.map(category=>`<li>${escapeHtml(category.name)}${category.restricted?" <span class=\"status-risk\">Restricted</span>":""}</li>`).join("");categorySelect.innerHTML=`<option value="">Select category…</option>${vaultCategories.map(category=>`<option value="${category.id}">${escapeHtml(category.name)}</option>`).join("")}`;const documentTarget=document.getElementById("documentsTable");documentTarget.innerHTML=documents.length?documents.slice().reverse().map(documentRecord=>{const category=documentCategory(documentRecord.categoryId);return `<tr><td>${escapeHtml(documentRecord.fileName)}<br><span class="hint">${escapeHtml(documentRecord.clientReference)}</span></td><td>${escapeHtml(category?.name||"Unclassified")}</td><td>${documentRecord.version}</td><td>${escapeHtml(documentRecord.uploadedAt.slice(0,16).replace("T"," "))}<br><span class="hint">${escapeHtml(documentRecord.uploadedBy)}</span></td><td class="${documentRecord.isLocked?"status-risk":"status-ok"}">${documentRecord.isLocked?"Locked":"Open"}</td><td><button data-document-action="view" data-id="${documentRecord.id}">View</button> <button data-document-action="download" data-id="${documentRecord.id}">Download</button> <button data-document-action="delete" data-id="${documentRecord.id}">Delete</button></td></tr>`}).join(""):'<tr><td colspan="6" class="hint">No document metadata registered.</td></tr>';const logTarget=document.getElementById("documentLogsTable");logTarget.innerHTML=documentLogs.length?documentLogs.slice().reverse().slice(0,20).map(log=>`<tr><td>${escapeHtml(log.actionTimestamp.slice(0,16).replace("T"," "))}</td><td>${escapeHtml(log.documentName)}</td><td class="${log.actionType.includes("BLOCKED")?"status-risk":""}">${escapeHtml(log.actionType)}</td><td>${escapeHtml(log.actorId)}</td></tr>`).join(""):'<tr><td colspan="4" class="hint">No document access events recorded.</td></tr>'}
function initialiseVault(){
  document.getElementById("documentForm").addEventListener("submit",event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),category=documentCategory(data.get("documentCategory")),engagementId=data.get("documentEngagement")||null,fileName=data.get("documentFileName").trim(),prior=documents.filter(documentRecord=>documentRecord.engagementId===engagementId&&documentRecord.categoryId===category.id&&documentRecord.fileName===fileName),version=prior.length?Math.max(...prior.map(item=>item.version))+1:1,record={id:crypto.randomUUID(),clientReference:data.get("documentClient").trim(),engagementId,categoryId:category.id,fileName,storageUrl:data.get("documentStorageUrl").trim(),fileSizeMb:Number(data.get("documentSize")||0),uploadedBy:data.get("documentUploadedBy").trim(),uploadedAt:new Date().toISOString(),isLocked:data.get("documentFinalReport")==="on",version};documents.push(record);logDocumentAction(record,"UPLOAD",record.uploadedBy);saveOperations();form.reset();refreshOperationalSelects();renderVault();renderDashboard();showVaultNotice(`${fileName} registered as Version ${version}${record.isLocked?" and locked":""}.`) });
  document.getElementById("documentsTable").addEventListener("click",event=>{const button=event.target.closest("button[data-document-action]");if(!button)return;const record=documents.find(documentRecord=>documentRecord.id===button.dataset.id);if(!record)return;const actorId=prompt("Enter your authenticated staff ID for the audit trail.");if(!actorId)return;if(button.dataset.documentAction==="view"||button.dataset.documentAction==="download"){logDocumentAction(record,button.dataset.documentAction.toUpperCase(),actorId);showVaultNotice(`${button.dataset.documentAction==="view"?"View":"Download"} request logged. Production will issue a 60-second presigned URL.`)}if(button.dataset.documentAction==="delete"){if(record.isLocked){logDocumentAction(record,"DELETE_BLOCKED",actorId);writeAlert("DOCUMENT_LOCK_BREACH",record.id,"Engagement Partner",`Blocked attempt to delete locked document ${record.fileName}.`);showVaultNotice("Deletion blocked. Locked documents can only be superseded by a new version.",true)}else if(confirm(`Delete document metadata for ${record.fileName}?`)){logDocumentAction(record,"DELETE",actorId);documents=documents.filter(documentRecord=>documentRecord.id!==record.id);showVaultNotice("Document metadata deleted. Production must retain the audit log.")}}saveOperations();renderVault();renderDashboard()});
  document.getElementById("requestPbc").addEventListener("click",()=>{const engagement=engagementById(document.getElementById("documentEngagement").value);if(!engagement){showVaultNotice("Select an active engagement before creating a PBC request.",true);return}const request={id:crypto.randomUUID(),engagementId:engagement.id,status:"Pending client upload",createdAt:new Date().toISOString(),recipient:"Client external upload portal"};pbcRequests.push(request);writeAlert("PBC_REQUEST",request.id,"Audit Supervisor",`PBC request created for ${engagement.companyName}.`);saveOperations();renderDashboard();showVaultNotice("PBC request created. Production will issue a single-use external upload link without an ERP login.")});
  document.getElementById("exportIcpak").addEventListener("click",()=>{const engagement=engagementById(document.getElementById("documentEngagement").value);if(!engagement){showVaultNotice("Select an active engagement before preparing an ICPAK export.",true);return}const packageDocs=documents.filter(documentRecord=>documentRecord.engagementId===engagement.id&&documentRecord.categoryId==="icpak-export");if(!packageDocs.length){showVaultNotice("Tag Trial Balance or Lead Schedule documents in the ICPAK export category first.",true);return}const exportRecord={id:crypto.randomUUID(),engagementId:engagement.id,documentIds:packageDocs.map(documentRecord=>documentRecord.id),createdAt:new Date().toISOString(),status:"Manifest prepared"};icpakExports.push(exportRecord);packageDocs.forEach(documentRecord=>logDocumentAction(documentRecord,"ICPAK_EXPORT_PREPARED","Manager"));saveOperations();renderVault();renderDashboard();showVaultNotice(`${packageDocs.length} document(s) added to the ICPAK export manifest. Production will create and log the secure package download.`)});renderVault()
}
function runFirmPulseControls(){activeEngagements().forEach(engagement=>{const wip=wipFor(engagement);if(engagement.potentialPie&&engagement.workflowTasks?.some(task=>task.id==="audit-eqr"&&task.status!=="Completed"))writeAlert("EQR_PENDING",engagement.id,"Engagement Partner",`Potential PIE quality review remains pending for ${engagement.companyName}.`);if(wip.agreedFee&&wip.costToFee>70)writeAlert("WIP_AT_RISK",engagement.id,"Engagement Partner",`Cost is ${wip.costToFee.toFixed(1)}% of agreed fee for ${engagement.companyName}.`);if(wip.agreedFee&&wip.actualCost>wip.agreedFee)writeAlert("WIP_AT_LOSS",engagement.id,"Engagement Partner",`${engagement.companyName} has actual cost above agreed fee. Record write-off or supplementary-invoice decision.`);if(engagement.stage==="WIP / Billing"&&wip.agreedFee&&wip.totalBilled===0)writeAlert("BILLING_PENDING",engagement.id,"Practice Administration",`${engagement.companyName} is in WIP / Billing with no recorded invoice.`)});documentLogs.filter(log=>log.actionType.includes("BLOCKED")).forEach(log=>writeAlert("DOCUMENT_LOCK_BREACH",log.documentId,"Engagement Partner",`Locked-document event for ${log.documentName}.`));runHrComplianceControls()}
function renderDashboard(){const active=activeEngagements(),allWip=active.map(wipFor),unbilled=allWip.reduce((sum,wip)=>sum+wip.unbilledWip,0),piePending=active.filter(engagement=>engagement.potentialPie&&engagement.workflowTasks?.some(task=>task.id==="audit-eqr"&&task.status!=="Completed")).length,overrun=allWip.filter(wip=>wip.agreedFee&&(wip.actualCost>wip.agreedFee||wip.costToFee>70)).length;document.getElementById("dashboardWip").textContent=formatKes(unbilled);document.getElementById("dashboardActiveEngagements").textContent=active.length;document.getElementById("dashboardPiePending").textContent=piePending;document.getElementById("dashboardOverrun").textContent=overrun;
  const sectors={};active.forEach(engagement=>{const wip=wipFor(engagement),bucket=sectors[engagement.primarySector]||{fee:0,cost:0};bucket.fee+=wip.agreedFee;bucket.cost+=wip.actualCost;sectors[engagement.primarySector]=bucket});const sectorTarget=document.getElementById("sectorRealization");sectorTarget.innerHTML=Object.keys(sectors).length?Object.entries(sectors).map(([sector,data])=>{const percent=data.fee?data.cost/data.fee*100:0;return `<tr><td>${escapeHtml(sector)}</td><td>${formatKes(data.fee)}</td><td>${formatKes(data.cost)}</td><td>${percent.toFixed(1)}%</td><td class="${percent>70?"status-risk":"status-ok"}">${percent>70?"At risk":"Within threshold"}</td></tr>`}).join(""):'<tr><td colspan="5" class="hint">No active financial baselines.</td></tr>';
  const branches={};invoices.filter(invoice=>invoice.datePaid).forEach(invoice=>{const branch=engagementById(invoice.engagementId)?.branchLocation||"Other",bucket=branches[branch]||0;branches[branch]=bucket+Number(invoice.amountBilled)});const branchTarget=document.getElementById("branchRevenue");branchTarget.innerHTML=Object.keys(branches).length?Object.entries(branches).map(([branch,value])=>`<tr><td>${escapeHtml(branch)}</td><td>${formatKes(value)}</td></tr>`).join(""):'<tr><td colspan="2" class="hint">No paid invoices recorded.</td></tr>';
  const controls=[];active.forEach(engagement=>{const wip=wipFor(engagement);if(engagement.potentialPie&&engagement.workflowTasks?.some(task=>task.id==="audit-eqr"&&task.status!=="Completed"))controls.push(["PIE / EQR",engagement.companyName,"Independent quality review remains pending","Attention"]);if(wip.agreedFee&&wip.costToFee>70)controls.push(["WIP profitability",engagement.companyName,`Cost / fee is ${wip.costToFee.toFixed(1)}%`,"At risk"]);if(wip.budgetVariance>0)controls.push(["Budget hours",engagement.companyName,`${wip.budgetVariance.toFixed(2)} hours over budget`,"At risk"])});documentLogs.filter(log=>log.actionType.includes("BLOCKED")).forEach(log=>controls.push(["Document vault",log.documentName,"Locked document action was blocked","Security"]));const controlTarget=document.getElementById("firmPulseTable");controlTarget.innerHTML=controls.length?controls.map(row=>`<tr><td>${escapeHtml(row[0])}</td><td>${escapeHtml(row[1])}</td><td>${escapeHtml(row[2])}</td><td class="status-risk">${escapeHtml(row[3])}</td></tr>`).join(""):'<tr><td colspan="4" class="hint">No current high-risk controls detected.</td></tr>';const alertTarget=document.getElementById("alertsTable");alertTarget.innerHTML=systemAlerts.length?systemAlerts.slice().reverse().slice(0,30).map(alert=>`<tr><td>${escapeHtml(alert.alertCode)}<br><span class="hint">${escapeHtml(alert.detail)}</span></td><td>${escapeHtml(alert.relatedRecordId)}</td><td>${escapeHtml(alert.recipientPosition)}</td><td>${escapeHtml(alert.status)}</td></tr>`).join(""):'<tr><td colspan="4" class="hint">No system alerts generated.</td></tr>'}
function initialiseDashboard(){document.getElementById("runFirmPulse").addEventListener("click",()=>{runFirmPulseControls();saveOperations();renderDashboard();showOperationsNotice("Firm Pulse controls completed. New alerts are available in the Executive Dashboard.")})}

function showHrNotice(message,error=false){const notice=document.getElementById("hrNotice");notice.textContent=message;notice.classList.add("show");notice.style.background=error?"#fbe8e8":"";notice.style.borderColor=error?"#d8aaaa":"";notice.style.color=error?"#8b2828":"";clearTimeout(showHrNotice.timer);showHrNotice.timer=setTimeout(()=>notice.classList.remove("show"),8000)}
function rangesOverlap(startA,endA,startB,endB){return startA<=endB&&endA>=startB}
function leaveIsBusySeason(startDate,endDate){const startYear=Number(startDate.slice(0,4)),endYear=Number(endDate.slice(0,4));for(let year=startYear;year<=endYear;year+=1){if(rangesOverlap(startDate,endDate,`${year}-01-15`,`${year}-04-30`))return true}return false}
function approvedLeaveOverlap(staffId,startDate,endDate){return leaveRequests.find(request=>request.staffId===staffId&&request.status==="Approved"&&rangesOverlap(startDate,endDate,request.startDate,request.endDate))}
function assignmentOverlap(staffId,startDate,endDate){return staffAssignments.find(assignment=>assignment.staffId===staffId&&rangesOverlap(startDate,endDate,assignment.plannedStartDate,assignment.plannedEndDate))}
function dayCount(startDate,endDate){return Math.floor((new Date(`${endDate}T00:00:00Z`)-new Date(`${startDate}T00:00:00Z`))/86400000)+1}
function activeFieldworkCount(staffId){return staffAssignments.filter(assignment=>assignment.staffId===staffId&&["Active Engagement","WIP / Billing"].includes(engagementById(assignment.engagementId)?.stage)).length}
function refreshHrSelects(){const active=activeEngagements();setSelectItems("assignmentEngagement",active);setSelectItems("reviewEngagement",lifecycleRecords.filter(record=>["Active Engagement","WIP / Billing","Closed / Archived"].includes(record.stage)),"Select engagement…")}
function updateHrRiskNotices(){const start=document.getElementById("leaveStartDate").value,end=document.getElementById("leaveEndDate").value,leaveNotice=document.getElementById("leaveRiskNotice"),staffId=document.getElementById("assignmentStaffId").value.trim(),assignmentStart=document.getElementById("assignmentStart").value,assignmentEnd=document.getElementById("assignmentEnd").value,assignmentNotice=document.getElementById("assignmentRiskNotice");leaveNotice.textContent=start&&end?(leaveIsBusySeason(start,end)?"Busy-season leave: this request must route to the Engagement Partner. The approval will be blocked while active fieldwork is assigned.":"Standard leave: Manager approval is sufficient unless a staffing conflict is identified."):"Enter leave dates to assess busy-season approval and active-fieldwork impact.";assignmentNotice.textContent=staffId&&assignmentStart&&assignmentEnd?(assignmentOverlap(staffId,assignmentStart,assignmentEnd)||approvedLeaveOverlap(staffId,assignmentStart,assignmentEnd)?"Conflict detected: this person is already assigned or on approved leave during part of the selected range. Allocation will be blocked.":"No current assignment or approved-leave conflict detected for this staff ID."):"The system blocks a person who has an overlapping engagement assignment or approved leave."}
function renderHr(){
  refreshHrSelects();updateHrRiskNotices();const today=operationDate(),days30=new Date(`${today}T00:00:00Z`);days30.setUTCDate(days30.getUTCDate()+30),deadline=days30.toISOString().slice(0,10),cpdHours=staffCredentials.filter(credential=>credential.credentialType==="CPD Seminar"&&credential.issueDate?.startsWith(today.slice(0,4))).reduce((sum,credential)=>sum+Number(credential.cpdHours||0),0),expiring=staffCredentials.filter(credential=>credential.expiryDate&&credential.expiryDate>=today&&credential.expiryDate<=deadline&&["ICPAK Membership","CPD Seminar"].includes(credential.credentialType)),busyLeaves=leaveRequests.filter(request=>request.blackoutRisk&&request.status==="Pending");document.getElementById("hrCpdHours").textContent=cpdHours.toFixed(2);document.getElementById("hrExpiringCredentials").textContent=expiring.length;document.getElementById("hrLeaveRisk").textContent=busyLeaves.length;document.getElementById("hrRosterConflicts").textContent=rosterConflicts.length;
  const roster=[...staffAssignments.map(assignment=>({kind:"assignment",staffId:assignment.staffId,label:engagementLabel(engagementById(assignment.engagementId)||{companyName:"Archived",initialService:"engagement"}),start:assignment.plannedStartDate,end:assignment.plannedEndDate,allocation:`${assignment.allocationPercentage}%`,status:"Assigned",id:assignment.id})),...leaveRequests.map(request=>({kind:"leave",staffId:request.staffId,label:`${request.leaveType} leave`,start:request.startDate,end:request.endDate,allocation:`${request.totalDays} days`,status:request.status,id:request.id,blackoutRisk:request.blackoutRisk}))].sort((a,b)=>a.start.localeCompare(b.start));const rosterTarget=document.getElementById("rosterTable");rosterTarget.innerHTML=roster.length?roster.map(item=>`<tr><td>${escapeHtml(item.staffId)}</td><td>${escapeHtml(item.label)}</td><td>${escapeHtml(item.start)} to ${escapeHtml(item.end)}</td><td>${escapeHtml(item.allocation)}</td><td class="${item.blackoutRisk&&item.status!=="Approved"?"status-risk":""}">${escapeHtml(item.status)}${item.blackoutRisk?" · Busy season":""}</td><td>${item.kind==="leave"&&item.status==="Pending"?`<button data-leave-action="approve" data-id="${item.id}">Approve</button> <button data-leave-action="reject" data-id="${item.id}">Reject</button>`:"—"}</td></tr>`).join(""):'<tr><td colspan="6" class="hint">No staff assignments or leave requests recorded.</td></tr>';
  const credentialsTarget=document.getElementById("credentialsTable");credentialsTarget.innerHTML=staffCredentials.length?staffCredentials.slice().reverse().map(credential=>`<tr><td>${escapeHtml(credential.staffId)}<br><span class="hint">${escapeHtml(credential.position)}</span></td><td>${escapeHtml(credential.credentialType)}<br><span class="hint">${escapeHtml(credential.description)}</span></td><td class="${credential.status==="Expired"?"status-risk":""}">${escapeHtml(credential.status)}</td><td>${Number(credential.cpdHours||0).toFixed(2)}</td><td class="${credential.expiryDate&&credential.expiryDate<=deadline?"status-risk":""}">${escapeHtml(credential.expiryDate||"—")}</td></tr>`).join(""):'<tr><td colspan="5" class="hint">No credentials or CPD entries recorded.</td></tr>';
  const performanceTarget=document.getElementById("performanceTable");performanceTarget.innerHTML=performanceReviews.length?performanceReviews.slice().reverse().map(review=>{const average=(Number(review.technicalScore)+Number(review.punctualityScore)+Number(review.workpaperScore))/3;return `<tr><td>${escapeHtml(engagementById(review.engagementId)?.companyName||"Archived engagement")}</td><td>${escapeHtml(review.revieweeStaffId)}</td><td>${review.technicalScore}</td><td>${review.punctualityScore}</td><td>${review.workpaperScore}</td><td>${average.toFixed(1)}</td></tr>`}).join(""):'<tr><td colspan="6" class="hint">No performance reviews recorded.</td></tr>'
}
function runHrComplianceControls(){const today=operationDate(),limit=new Date(`${today}T00:00:00Z`);limit.setUTCDate(limit.getUTCDate()+30);const deadline=limit.toISOString().slice(0,10);staffCredentials.filter(credential=>credential.expiryDate&&credential.expiryDate>=today&&credential.expiryDate<=deadline&&["ICPAK Membership","CPD Seminar"].includes(credential.credentialType)).forEach(credential=>writeAlert("CREDENTIAL_EXPIRY",credential.id,"Practice Administration",`${credential.credentialType} for staff ID ${credential.staffId} expires on ${credential.expiryDate}.`));timesheets.filter(entry=>entry.status==="Approved Leave"&&entry.entryType==="Sick Leave").forEach(entry=>writeAlert("SICK_LEAVE_RECORDED",entry.id,"Manager",`Approved sick leave was reflected in availability for staff ID ${entry.staffId}.`))}
function initialiseHR(){
  document.getElementById("credentialForm").addEventListener("submit",event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form);staffCredentials.push({id:crypto.randomUUID(),staffId:data.get("credentialStaffId").trim(),position:data.get("credentialPosition"),credentialType:data.get("credentialType"),description:data.get("credentialDescription").trim(),status:data.get("credentialStatus"),issueDate:data.get("credentialIssueDate")||null,expiryDate:data.get("credentialExpiryDate")||null,cpdHours:Number(data.get("credentialCpdHours")||0),documentReference:data.get("credentialDocumentRef").trim(),createdAt:new Date().toISOString()});saveOperations();form.reset();renderHr();showHrNotice("Credential or CPD entry recorded. Production will restrict this information to HR and authorized quality roles.")});
  ["leaveStartDate","leaveEndDate","assignmentStaffId","assignmentStart","assignmentEnd"].forEach(id=>document.getElementById(id).addEventListener("input",updateHrRiskNotices));document.getElementById("leaveForm").addEventListener("submit",event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),startDate=data.get("leaveStartDate"),endDate=data.get("leaveEndDate"),staffId=data.get("leaveStaffId").trim();if(endDate<startDate){showHrNotice("Leave end date cannot be earlier than the start date.",true);return}const blackoutRisk=leaveIsBusySeason(startDate,endDate),request={id:crypto.randomUUID(),staffId,leaveType:data.get("leaveType"),startDate,endDate,totalDays:dayCount(startDate,endDate),status:"Pending",blackoutRisk,blackoutOverride:false,approvalRoute:blackoutRisk?"Engagement Partner":"Manager",createdAt:new Date().toISOString()};leaveRequests.push(request);if(blackoutRisk)writeAlert("BUSY_SEASON_LEAVE",request.id,"Engagement Partner",`Busy-season leave request submitted by staff ID ${staffId}.`);saveOperations();form.reset();renderHr();showHrNotice(blackoutRisk?"Busy-season leave request submitted to the Engagement Partner for review.":"Leave request submitted for Manager approval.")});
  document.getElementById("assignmentForm").addEventListener("submit",event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),staffId=data.get("assignmentStaffId").trim(),startDate=data.get("assignmentStart"),endDate=data.get("assignmentEnd"),engagementId=data.get("assignmentEngagement");if(endDate<startDate){showHrNotice("Assignment end date cannot be earlier than its start date.",true);return}const assignmentConflict=assignmentOverlap(staffId,startDate,endDate),leaveConflict=approvedLeaveOverlap(staffId,startDate,endDate);if(assignmentConflict||leaveConflict){rosterConflicts.push({id:crypto.randomUUID(),staffId,startDate,endDate,reason:assignmentConflict?"Overlapping engagement assignment":"Approved leave conflict",createdAt:new Date().toISOString()});writeAlert("ROSTER_CONFLICT",staffId,"Manager",`Assignment blocked for staff ID ${staffId} due to ${assignmentConflict?"overlapping fieldwork":"approved leave"}.`);saveOperations();renderHr();showHrNotice("Allocation blocked because this staff ID has an overlapping assignment or approved leave.",true);return}staffAssignments.push({id:crypto.randomUUID(),engagementId,staffId,roleOnJob:data.get("assignmentRole"),plannedStartDate:startDate,plannedEndDate:endDate,allocationPercentage:Number(data.get("assignmentAllocation")),createdAt:new Date().toISOString()});saveOperations();form.reset();renderHr();showHrNotice("Staff assignment added to the resource roster.")});
  document.getElementById("performanceForm").addEventListener("submit",event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form);performanceReviews.push({id:crypto.randomUUID(),engagementId:data.get("reviewEngagement"),reviewerStaffId:data.get("reviewerStaffId").trim(),revieweeStaffId:data.get("revieweeStaffId").trim(),technicalScore:Number(data.get("technicalScore")),punctualityScore:Number(data.get("punctualityScore")),workpaperScore:Number(data.get("workpaperScore")),comments:data.get("reviewComments").trim(),reviewDate:data.get("reviewDate"),createdAt:new Date().toISOString()});saveOperations();form.reset();renderHr();showHrNotice("Performance review recorded with the engagement quality record.")});
  document.getElementById("rosterTable").addEventListener("click",event=>{const button=event.target.closest("button[data-leave-action]");if(!button)return;const request=leaveRequests.find(item=>item.id===button.dataset.id);if(!request)return;if(button.dataset.leaveAction==="reject"){const reason=prompt("Enter the leave rejection reason.");if(!reason)return;request.status="Rejected";request.rejectionReason=reason;showHrNotice("Leave request rejected with reason.")}else{const approver=prompt(`Enter the ${request.blackoutRisk?"Engagement Partner":"Manager"} staff ID approving this leave.`);if(!approver)return;const activeCount=activeFieldworkCount(request.staffId);if(request.blackoutRisk&&activeCount>0){showHrNotice(`Busy-season leave cannot be approved while ${request.staffId} has ${activeCount} active fieldwork assignment(s).`,true);return}request.status="Approved";request.approvedBy=approver;request.approvedAt=new Date().toISOString();request.blackoutOverride=request.blackoutRisk; if(request.leaveType==="Sick"){for(let offset=0;offset<request.totalDays;offset+=1)timesheets.push({id:crypto.randomUUID(),staffId:request.staffId,position:"",engagementId:null,taskId:null,dateLogged:addDays(request.startDate,offset),hoursSpent:8,description:"Approved sick leave availability entry",status:"Approved Leave",approvedBy:approver,approvedAt:new Date().toISOString(),locked:true,entryType:"Sick Leave",createdAt:new Date().toISOString()})}showHrNotice("Leave approved. Approved sick leave is reflected in the staff availability record.")}saveOperations();renderHr();renderOperations();renderDashboard()});renderHr()
}

renderStaticFields();renderAccessControl();initialiseTabs();initialiseForm();listenForClientActions();initialiseLifecycle();initialiseOperations();initialiseHR();initialiseVault();initialiseDashboard();showRecommendation();showTaxComplianceProfile();renderClientList();
